const REPOSITORY_URL = 'https://github.com/wangjinmiao147-dotcom/rp-cinematic-imagegen';
const EXTENSION_ID = 'rp-cinematic-imagegen';
const LEGACY_EXTENSION_ID = 'rp-cinematic-v2';
const BUTTON_NAME = '安装 / 更新 RP 电影配图';
let operationInProgress = false;

async function responseMessage(response) {
  try {
    const data = await response.clone().json();
    return data?.message || JSON.stringify(data);
  } catch {
    try {
      return await response.text();
    } catch {
      return '';
    }
  }
}

function reloadAfterSuccess(message) {
  toastr.success(`${message}，即将刷新酒馆页面…`);
  setTimeout(() => triggerSlash('/reload-page'), 1800);
}

async function installOrUpdate({ automatic = false } = {}) {
  if (operationInProgress) {
    if (!automatic) toastr.info('安装或更新正在进行，请稍候。');
    return;
  }

  operationInProgress = true;
  try {
    if (isInstalledExtension(EXTENSION_ID)) {
      if (automatic) return;

      toastr.info('正在检查并更新 RP 电影配图…');
      const response = await updateExtension(EXTENSION_ID);
      if (!response.ok) {
        throw new Error((await responseMessage(response)) || `HTTP ${response.status}`);
      }
      reloadAfterSuccess('RP 电影配图更新完成');
      return;
    }

    const migratingLegacy = isInstalledExtension(LEGACY_EXTENSION_ID);
    toastr.info(migratingLegacy
      ? '检测到旧版，正在安全迁移到完整正式版…'
      : '正在从 GitHub 安装 RP 电影配图完整正式版…');
    const response = await installExtension(REPOSITORY_URL, 'local');
    if (!response.ok) {
      throw new Error((await responseMessage(response)) || `HTTP ${response.status}`);
    }

    if (migratingLegacy) {
      const removeLegacyResponse = await uninstallExtension(LEGACY_EXTENSION_ID);
      if (!removeLegacyResponse.ok) {
        throw new Error(`完整正式版已安装，但旧版清理失败：${(await responseMessage(removeLegacyResponse)) || `HTTP ${removeLegacyResponse.status}`}。请刷新后在扩展管理中停用 rp-cinematic-v2，避免重复加载。`);
      }
      reloadAfterSuccess('RP 电影配图已迁移为完整正式版');
      return;
    }

    reloadAfterSuccess('RP 电影配图完整正式版安装完成');
  } catch (error) {
    console.error('[RP 电影配图安装器]', error);
    toastr.error(`RP 电影配图安装/更新失败：${error?.message || error}`);
  } finally {
    operationInProgress = false;
  }
}

eventOn(getButtonEvent(BUTTON_NAME), () => void installOrUpdate());
void installOrUpdate({ automatic: true });
